#include <dolphin/types.h>

// Placement/texture of a sprite for one language (12 bytes).
typedef struct MenuSpriteVal {
    s16 x;               // 0x00
    s16 y;               // 0x02
    s16 w;               // 0x04
    s16 h;               // 0x06
    u16 resId;           // 0x08 texture resource id
    u8 format;           // 0x0A
    u8 unk0B;            // 0x0B
} MenuSpriteVal;

// One menu sprite (72 bytes): header, one MenuSpriteVal per language, link.
typedef struct MenuSpriteEntry {
    u8 flags;            // 0x00
    u8 unk1;             // 0x01
    u8 unk2;             // 0x02
    u8 unk3;             // 0x03
    u8 unk4;             // 0x04
    u8 alpha;            // 0x05
    u16 unk6;            // 0x06
    MenuSpriteVal val[5];// 0x08 languages (index = language - 2)
    s16 next;            // 0x44 next sprite in the chain
    s16 unk46;           // 0x46
} MenuSpriteEntry;

